type MarylandRouteSpec = {
  id: string;
  riverId: string;
  name: string;
  reach: string;
  aliases: string[];
  region: string;
  latitude: number;
  longitude: number;
  putIn: { name: string; latitude: number; longitude: number };
  takeOut: { name: string; latitude: number; longitude: number };
  accessPoints: Array<{
    id: string;
    name: string;
    latitude: number;
    longitude: number;
    mileFromStart: number;
    note: string;
  }>;
  distanceLabel: string;
  paddleTime: string;
  summary: string;
  statusText: string;
  thresholdSource: { label: string; url: string; provider: 'nps' | 'american_whitewater' | 'local' };
  thresholdModel: 'minimum-only' | 'two-sided';
  gaugeSiteId: string;
  gaugeSiteName: string;
  gaugeMetric: 'gage_height_ft' | 'discharge_cfs';
  gaugeUnit: 'ft' | 'cfs';
  gaugeKind: 'direct' | 'proxy';
  tooLow?: number;
  idealMin?: number;
  idealMax?: number;
  tooHigh?: number;
  routeType: 'recreational' | 'whitewater';
  difficulty: 'easy' | 'moderate' | 'hard';
  riskLevel: RouteSafetyProfile['riskLevel'];
  hazards: RouteSafetyProfile['hazards'];
  safetyNotes: string[];
  shuttle: string;
  camping: string;
  campingClassification: 'none' | 'nearby_basecamp' | 'endpoint_campground' | 'on_route_campsite';
  permits: string;
  accessCaveats: string[];
  watchFor: string[];
  evidenceNotes: Array<{ label: string; value: string; note: string; sourceUrl: string }>;
  sourceLinks: Array<{ label: string; url: string; provider: 'nps' | 'usgs' | 'american_whitewater' | 'local' | 'manual' }>;
  contextImageUrl: string;
  contextImageNote: string;
};

function buildMarylandRoute(spec: MarylandRouteSpec): River {
  const detailUrl = `https://waterdata.usgs.gov/monitoring-location/USGS-${spec.gaugeSiteId}/`;
  const hydrographUrl = `https://waterdata.usgs.gov/nwis/uv/?referred_module=sw&site_no=${spec.gaugeSiteId}`;
  return {
    id: spec.id,
    riverId: spec.riverId,
    slug: spec.id,
    name: spec.name,
    reach: spec.reach,
    aliases: spec.aliases,
    state: 'Maryland',
    region: spec.region,
    routeType: spec.routeType,
    summary: spec.summary,
    statusText: spec.statusText,
    latitude: spec.latitude,
    longitude: spec.longitude,
    safetyProfile: {
      riskLevel: spec.riskLevel,
      hazards: spec.hazards,
      safetyNotes: spec.safetyNotes,
      reviewStatus: 'reviewed',
    },
    gaugeSource: {
      id: `usgs-${spec.gaugeSiteId}`,
      provider: 'usgs',
      siteId: spec.gaugeSiteId,
      metric: spec.gaugeMetric,
      unit: spec.gaugeUnit,
      kind: spec.gaugeKind,
      siteName: spec.gaugeSiteName,
      detailUrl,
      hydrographUrl,
    },
    profile: {
      thresholdModel: spec.thresholdModel,
      ...(typeof spec.tooLow === 'number' ? { tooLow: spec.tooLow } : {}),
      ...(typeof spec.idealMin === 'number' ? { idealMin: spec.idealMin } : {}),
      ...(typeof spec.idealMax === 'number' ? { idealMax: spec.idealMax } : {}),
      ...(typeof spec.tooHigh === 'number' ? { tooHigh: spec.tooHigh } : {}),
      thresholdSource: spec.thresholdSource,
      thresholdSourceStrength: 'official',
      rainfallSensitivity: 'high',
      seasonMonths: [3, 4, 5, 6, 7, 8, 9, 10, 11],
      seasonNotes: 'Spring through fall is the practical planning season, but Maryland water levels, recent rain, temperature, debris, and daylight control every launch decision.',
      difficulty: spec.difficulty,
      difficultyNotes: spec.routeType === 'whitewater'
        ? 'This is a whitewater route. The river source and current local conditions must be matched to the paddler’s demonstrated rescue, scouting, and cold-water skills.'
        : 'The source describes recreational moving water, but shallow rock, current, cold water, debris, and bridge or access hazards remain material.',
      confidenceNotes: 'High route-shape confidence: public agency or National Park Service material names the corridor and access context. Coordinates are access-area or water-entry anchors, not a promise that a ramp, parking lot, or landing is open on launch day. Numeric guidance is intentionally conservative and never replaces visual inspection.',
    },
    putIn: spec.putIn,
    takeOut: spec.takeOut,
    accessPoints: spec.accessPoints.map((point) => ({ ...point, segmentKind: 'transition' as const })),
    logistics: {
      distanceLabel: spec.distanceLabel,
      estimatedPaddleTime: spec.paddleTime,
      shuttle: spec.shuttle,
      permits: spec.permits,
      camping: spec.camping,
      campingClassification: spec.campingClassification,
      summary: spec.summary,
      accessCaveats: spec.accessCaveats,
      watchFor: spec.watchFor,
    },
    evidenceNotes: [
      ...spec.evidenceNotes,
      { label: 'Live gauge', value: `USGS ${spec.gaugeSiteId}, ${spec.gaugeSiteName}`, note: spec.gaugeKind === 'proxy' ? 'This is a clearly labeled proxy or route-context station; local water, tributaries, releases, and weather can differ materially.' : 'This is a direct same-river station. Readings are provisional and must be combined with trend and visual conditions.', sourceUrl: hydrographUrl },
      { label: 'Approved route imagery', value: 'Rights-cleared public-agency or public-domain corridor image', note: spec.contextImageNote, sourceUrl: spec.contextImageUrl },
    ],
    sourceLinks: [
      ...spec.sourceLinks,
      { label: `USGS ${spec.gaugeSiteId} monitoring location`, url: detailUrl, provider: 'usgs' },
      { label: `USGS ${spec.gaugeSiteId} current conditions`, url: hydrographUrl, provider: 'usgs' },
      { label: 'Approved corridor image', url: spec.contextImageUrl, provider: 'manual' },
    ],
    scoreEligibility: spec.gaugeKind === 'direct' && spec.thresholdModel === 'two-sided' ? 'scored' : 'planning',
    scoreEligibilityReason: spec.gaugeKind === 'proxy' ? 'proxy_gauge' : undefined,
  };
}

